import sys,re; sys.path.insert(0,'tools')
from ledger_io import load_jsonl_union
from pathlib import Path
nt=load_jsonl_union(Path('state/notes.jsonl'),'note_id')
def hs(p):
    return [m.group(1).strip() for l in open(p,encoding='utf-8',errors='ignore') if (m:=re.match(r'^#{2,3}\s+(.*)',l))]
def ix(h,n):
    pat=re.compile(r'^'+re.escape(n)+r'(?=$|[\s.．、・)）\-–])'); return [i for i,x in enumerate(h) if pat.match(x)]
b={'printed_lt24':0,'harvested_24_59':0,'beyond_60':0,'missing':0}
for x in nt.values():
    if not x.get('claims') or not x.get('path'): continue
    h=hs(x['path'])
    for c in x['claims']:
        for n in re.findall(r'§\s*(\d+(?:\.\d+)*)',c.get('anchor') or ''):
            i=ix(h,n)
            k='missing' if not i else ('printed_lt24' if min(i)<24 else ('harvested_24_59' if min(i)<60 else 'beyond_60'))
            b[k]+=1
print(b)
EOF
